import{_ as t,o as a,c as i,a3 as s}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Construire, valider et publier","description":"Préparer et valider les paquets de plugins et catalogues ATLAS.","frontmatter":{"title":"Construire, valider et publier","description":"Préparer et valider les paquets de plugins et catalogues ATLAS."},"headers":[],"relativePath":"fr/projects/atlas-plugins/developers/publishing.md","filePath":"fr/projects/atlas-plugins/developers/publishing.md","lastUpdated":1792851046000}'),l={name:"fr/projects/atlas-plugins/developers/publishing.md"};function n(r,e,o,p,u,d){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="construire-valider-et-publier" tabindex="-1">Construire, valider et publier <a class="header-anchor" href="#construire-valider-et-publier" aria-label="Permalink to &quot;Construire, valider et publier&quot;">​</a></h1><p>Le <a href="./../plugin-template">modèle de plugin</a> automatise les étapes répétitives du dépôt GitHub d&#39;un plugin.</p><h2 id="generer-le-paquet-et-le-catalogue" tabindex="-1">Générer le paquet et le catalogue <a class="header-anchor" href="#generer-le-paquet-et-le-catalogue" aria-label="Permalink to &quot;Générer le paquet et le catalogue&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>La génération crée un paquet installable à partir du manifeste et synchronise l&#39;entrée correspondante dans <code>repository.json</code>. Les contrôles vérifient notamment les identifiants, le chemin du paquet et les métadonnées du paquet généré. GitHub Actions lance ces commandes à chaque push et pull request.</p><h2 id="etapes-de-publication" tabindex="-1">Étapes de publication <a class="header-anchor" href="#etapes-de-publication" aria-label="Permalink to &quot;Étapes de publication&quot;">​</a></h2><p>Respecter les <a href="./compatibility">règles de version et de compatibilité</a>, notamment les sauvegardes, limites de migration et procédures de restauration.</p><ol><li>Augmentez la valeur <code>version</code> du manifeste à chaque publication fonctionnelle ou visible.</li><li>Exécutez <code>npm run build</code> et <code>npm run check</code>.</li><li>Vérifiez que le manifeste, le catalogue et le paquet généré indiquent le même identifiant et la même version.</li><li>Contrôlez les fichiers, les chemins des ressources, les requêtes externes et les capacités déclarées.</li><li>Publier le catalogue par push vers <code>main</code> : <code>https://raw.githubusercontent.com/&lt;owner&gt;/&lt;repo&gt;/main/repository.json</code>. GitHub Pages n’est pas nécessaire pour ce fichier brut ; l’activer éventuellement pour <code>install.html</code>.</li><li>Ajoutez l&#39;URL du catalogue dans l&#39;Administration ATLAS et testez l&#39;aperçu et l&#39;installation du paquet.</li></ol><p>Conservez l&#39;identifiant du plugin après sa première publication. Le format de paquet étant textuel, hébergez séparément les gros fichiers binaires et référencez-les par URL.</p><h2 id="etat-de-l-installation" tabindex="-1">État de l&#39;installation <a class="header-anchor" href="#etat-de-l-installation" aria-label="Permalink to &quot;État de l&#39;installation&quot;">​</a></h2><p>Le serveur App installe les paquets validés, depuis un dépôt ou un import, dans le stockage persistant et sert les fichiers web sous <code>/plugin-assets/&lt;slug&gt;/</code>. Leur JavaScript s’exécute dans le navigateur à l’ouverture ; les modules Node ou hooks Runtime ne sont pas enregistrés automatiquement. Ce n’est pas une sandbox : vérifier paquet et code avant ouverture. La génération seule ne remplace pas les contrôles d’exécution et de sécurité.</p>`,11)])])}const m=t(l,[["render",n]]);export{h as __pageData,m as default};
